const request = $json || {};
const expected = 'REPLACE_WITH_EVIDENCE_GATEWAY_TOKEN';
const received = String(request.headers?.authorization || request.headers?.Authorization || '').replace(/^Bearer\s+/i, '').trim();
const tokenEquals = (left, right) => { if (!left || left.length !== right.length) return false; let diff = 0; for (let index = 0; index < left.length; index += 1) diff |= left.charCodeAt(index) ^ right.charCodeAt(index); return diff === 0; };
if (!tokenEquals(received, expected)) return [{ json: { valid: false, status: 'unauthorized', errors: ['Unauthorized evidence gateway request.'] } }];
const raw = request.body ?? request;
const allowedFields = new Set(['countryCode', 'table', 'anomalyDate', 'baselineDate', 'metricHint']);
const aliases = { id: 'ine', indonesia: 'ine', cn: 'cn', china: 'cn', ph: 'ph', philippines: 'ph', th: 'th', thailand: 'th', pk: 'pk', pakistan: 'pk', mx: 'mx', mexico: 'mx' };
const isObject = raw && typeof raw === 'object' && !Array.isArray(raw);
const countryCode = aliases[String(isObject ? raw.countryCode || '' : '').trim().toLowerCase()];
const table = String(isObject ? raw.table || '' : '').trim().toLowerCase();
const anomalyDate = String(isObject ? raw.anomalyDate || '' : '').trim();
const baselineDate = String(isObject ? raw.baselineDate || '' : '').trim();
const metricHint = isObject && raw.metricHint !== undefined ? String(raw.metricHint).trim().slice(0, 120) : undefined;
const errors = [];
if (!isObject) errors.push('Request body must be a JSON object.');
if (isObject && Object.keys(raw).some((key) => !allowedFields.has(key))) errors.push('Only countryCode, table, anomalyDate, baselineDate, and optional metricHint are accepted.');
if (!countryCode) errors.push('Unsupported countryCode; use cn, ine/id, ph, th, pk, or mx.');
if (!/^[a-z][a-z0-9_]{0,127}\.[a-z][a-z0-9_]{0,127}$/.test(table)) errors.push('table must be a lowercase schema.table identifier.');
const parseDate = (value) => { if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null; const date = new Date(value + 'T00:00:00Z'); return Number.isNaN(date.valueOf()) || date.toISOString().slice(0, 10) !== value ? null : date; };
const anomaly = parseDate(anomalyDate); const baseline = parseDate(baselineDate);
if (!anomaly || !baseline) errors.push('anomalyDate and baselineDate must be real YYYY-MM-DD dates.');
if (anomaly && baseline && (anomaly < baseline || (anomaly - baseline) / 86400000 > 31)) errors.push('baselineDate must be on or before anomalyDate and within 31 days.');
if (errors.length) return [{ json: { valid: false, status: 'invalid_request', errors } }];
const [schema, tableName] = table.split('.');
const quoteIdentifier = (value) => '`' + value.replace(/`/g, '') + '`';
const quoteDate = (value) => "'" + value + "'";
const target = quoteIdentifier(schema) + '.' + quoteIdentifier(tableName);
const buildProbe = (label, date) => "SELECT '" + label + "' AS evidence_type, " + quoteDate(date) + " AS requested_partition_date, COUNT(*) AS observed_row_count, MAX(dt) AS observed_partition_date FROM " + target + " WHERE dt = " + quoteDate(date);
const query = buildProbe('anomaly', anomalyDate) + ' UNION ALL ' + buildProbe('baseline', baselineDate);
return [{ json: { valid: true, countryCode, table, anomalyDate, baselineDate, metricHint, query } }];

const source = $('Validate And Build Fixed Partition Evidence').first().json;
const executionError = $json.error?.message || $json.message || null;
if (executionError) return [{ json: { status: 'unavailable', countryCode: source.countryCode, table: source.table, anomalyDate: source.anomalyDate, baselineDate: source.baselineDate, metricHint: source.metricHint, reason: 'connector_unavailable', evidence: [], retryable: true } }];
const rows = $input.all().map((item) => item.json).filter((row) => row && row.evidence_type);
const evidence = rows.map((row) => { const available = row.observed_partition_date !== null && row.observed_partition_date !== undefined; return { evidenceType: row.evidence_type, requestedPartitionDate: row.requested_partition_date, availability: available ? 'available' : 'unavailable', rowCount: available ? Number(row.observed_row_count) : null, observedPartitionDate: available ? String(row.observed_partition_date).slice(0, 10) : null }; });
if (!evidence.length || evidence.some((row) => row.availability === 'unavailable')) return [{ json: { status: 'unavailable', countryCode: source.countryCode, table: source.table, anomalyDate: source.anomalyDate, baselineDate: source.baselineDate, metricHint: source.metricHint, reason: 'date_partition_unavailable', evidence, retryable: false } }];
return [{ json: { status: 'ok', countryCode: source.countryCode, table: source.table, anomalyDate: source.anomalyDate, baselineDate: source.baselineDate, metricHint: source.metricHint, evidence } }];
